The following R3F scene is lagging on a laptop GPU.
Diagnose every performance issue and fix them. Keep the same visual result: a slowly rotating blue sphere.

// BEFORE
import { Canvas, useFrame } from '@react-three/fiber';
import { useRef } from 'react';
function Sphere() {
  const ref = useRef();
  useFrame(() => { if (ref.current) ref.current.rotation.y += 0.01; });
  return <mesh ref={ref}><sphereGeometry args={[1, 128, 128]} /><meshStandardMaterial color='royalblue' /></mesh>;
}
export default function LaggyScene() {
  return (
    <Canvas dpr={[1, 3]}>
      <ambientLight intensity={1} /><pointLight position={[0,5,0]} intensity={2} />
      <pointLight position={[5,0,0]} intensity={2} /><pointLight position={[-5,0,0]} intensity={2} />
      <directionalLight position={[0,10,10]} intensity={2} /><spotLight position={[0,10,0]} intensity={3} />
      <Sphere />
    </Canvas>
  );
}
